<?php
declare(strict_types=1);session_start();require_once __DIR__ . '/config/product_step11.php';if(empty($_SESSION['product_import_csrf']))$_SESSION['product_import_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['product_import_csrf'];$error=null;$success=null;$jobs=[];$known=[];
try{$pdo=business_db();product_step11_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];$market=product_step11_market($pdo,$orgId);$marketId=(int)$market['id'];$data=product_step11_seed_data();$known=[strtolower($data['associate_pdf_sha256'])=>'Associate Price List - India • 15 Apr 2026',strtolower($data['preferred_pdf_sha256'])=>'Preferred Customer Price List • 15 Apr 2026'];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');if(!isset($_FILES['price_pdf'])||!is_array($_FILES['price_pdf']))throw new RuntimeException('Choose a PDF file.');$f=$_FILES['price_pdf'];if((int)($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('PDF upload failed.');$tmp=(string)$f['tmp_name'];$name=basename((string)$f['name']);$size=(int)($f['size']??0);if($size<=0||$size>15*1024*1024)throw new RuntimeException('PDF must be between 1 byte and 15 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);if($mime!=='application/pdf')throw new RuntimeException('Only PDF files are accepted.');$hash=strtolower(hash_file('sha256',$tmp));$recognized=isset($known[$hash]);$status=$recognized?'recognized':'review_required';$effective=$recognized?PRODUCT_STEP11_EFFECTIVE_DATE:null;$stmt=$pdo->prepare("INSERT INTO product_import_jobs(organization_id,market_id,import_type,original_file_name,file_sha256,effective_date,status,total_rows,matched_rows,review_rows,notes) VALUES(?,?,'price_pdf',?,?,?,?,?,?,?,?)");$sourceCount=count($data['products']);$stmt->execute([$orgId,$marketId,$name,$hash,$effective,$status,$recognized?$sourceCount:0,$recognized?$sourceCount:0,$recognized?0:1,$recognized?$known[$hash]:'Unknown PDF hash: no product/price write performed. Review required.']);$jobId=(int)$pdo->lastInsertId();if($recognized&&($_POST['apply_recognized']??'')==='yes'){$result=product_step11_apply_seed($pdo);$pdo->prepare("UPDATE product_import_jobs SET status='applied',matched_rows=?,review_rows=0,updated_at=NOW() WHERE id=? AND organization_id=?")->execute([(int)$result['products'],$jobId,$orgId]);$success='Recognized source verified and reconciled: '.$known[$hash].'.';}elseif($recognized){$success='Recognized PDF: '.$known[$hash].'. It was staged only; tick Apply to reconcile the catalog.';}else{$success='Unknown/new PDF staged as REVIEW REQUIRED. No product or price was changed.';}if(business_table_exists($pdo,'audit_logs')){$a=$pdo->prepare("INSERT INTO audit_logs(organization_id,event_type,entity_type,entity_id,details_json) VALUES(?,'product_pdf_import_staged','product_import_job',?,?)");$a->execute([$orgId,$jobId,json_encode(['file'=>$name,'sha256'=>$hash,'recognized'=>$recognized,'status'=>$status],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);}}
$stmt=$pdo->prepare("SELECT id,original_file_name,file_sha256,effective_date,status,total_rows,matched_rows,review_rows,created_at FROM product_import_jobs WHERE organization_id=? ORDER BY id DESC LIMIT 30");$stmt->execute([$orgId]);$jobs=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?>
