eview required' ?></span><span class="os-chip good">2 reviewed hashes</span><span class="os-chip">Unknown source: staged only</span></div></section><?php if($success):?><div class="pp-alert good"><?= product_h($success) ?></div><?php endif;?><?php if($error):?><div class="pp-alert bad"><?= product_h($error) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid"><article class="os-card pp-span-5"><h2>Upload Price List</h2><form method="post" enctype="multipart/form-data" class="pp-form"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><label>PDF file<input type="file" name="price_pdf" accept="application/pdf,.pdf" required></label><label class="pp-check"><input type="checkbox" name="apply_recognized" value="yes"><span>If this exact hash is already reviewed, reconcile it immediately.</span></label><button>Inspect PDF Hash →</button></form></article><article class="os-card pp-span-7"><h2>Recognized Sources</h2><?php foreach($known as $hash=>$title):?><div class="pp-source"><b><?= product_h($title) ?></b><span><?= product_h($hash) ?></span><small>Exact hash recognition only. Filename alone is never trusted.</small></div><?php endforeach;?></article><article class="os-card pp-span-12"><div class="os-title-row"><div><h2>Recent Import Jobs</h2><p>Unknown PDFs remain review-only evidence.</p></div></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>ID</th><th>File</th><th>SHA-256</th><th>Effective</th><th>Status</th><th>Matched</th><th>Review</th><th>Created</th></tr></thead><tbody><?php foreach($jobs as $j):?><tr><td>#<?= (int)$j['id'] ?></td><td><?= product_h($j['original_file_name']) ?></td><td style="max-width:280px;overflow-wrap:anywhere"><?= product_h($j['file_sha256']) ?></td><td><?= product_h($j['effective_date']?:'—') ?></td><td><span class="pp-badge <?= $j['status']==='review_required'?'warn':'' ?>"><?= product_h(strtoupper($j['status'])) ?></span></td><td><?= number_format((int)$j['matched_rows']) ?></td><td><?= number_format((int)$j['review_rows']) ?></td><td><?= product_h($j['created_at']) ?></td></tr><?php endforeach;?></tbody></table></div></article></section><?php endif;?></main></div></body></html>